/* From Uiverse.io by ahmed150up - Tags: loader */
.__UIV_SCOPE__ .loader {
  display: flex;
  justify-content: center;
}

.__UIV_SCOPE__ .bar {
  width: 7px;
  height: 18px;
  margin: 0 9px;
  border-radius: 10px;
  animation: loading_5192 1s ease-in-out infinite;
  background-color: aqua;
}

.__UIV_SCOPE__ .bar:nth-child(1) {
  animation-delay: 0.01s;
}

.__UIV_SCOPE__ .bar:nth-child(2) {
  animation-delay: 0.09s;
}

.__UIV_SCOPE__ .bar:nth-child(3) {
  animation-delay: 0.19s;
}

.__UIV_SCOPE__ .bar:nth-child(4) {
  animation-delay: 0.29s;
}

@keyframes loading_5192 {
  0% {
    transform: scale(1);
  }

  20% {
    transform: scale(1, 2.5);
  }

  40% {
    transform: scale(1);
  }
}
